/*
 * SPDX-License-Identifier: MIT
 *
 * Home Assistant app core: Material Design Icons names to codepoints (no LVGL; tests/test_tiles.cpp).
 *
 * The table is mdi-names.bin, generated by tools/make_mdi.py from @mdi/svg 7.4.47's meta.json (every icon name and alias,
 * sorted): "MDN1", u32 count, 16 bytes version, count x u32 offsets into the blob, then per entry "name\0" and the
 * codepoint as 3 bytes, little-endian. It is mapped read-only (only the pages a lookup touches are read: about 15 per
 * name) and searched by binary search. Read-only after open(): any thread may call lookup().
 *
 * The font is materialdesignicons-webfont.ttf (the same version), drawn by the toolkit's FreeType at any size; a name
 * maps to a codepoint in U+F0001..U+F1D17 (plane 15, private use), written into a label as 4 bytes of UTF-8.
 */
#pragma once

#include <cstddef>
#include <cstdint>
#include <string>

namespace ha {

class MdiNames {
public:
    MdiNames() = default;
    ~MdiNames();
    MdiNames(const MdiNames &) = delete;
    MdiNames &operator=(const MdiNames &) = delete;

    /* Maps the file; false (and no table) when it is missing or malformed. */
    bool open(const std::string &path);
    bool loaded() const { return count_ > 0; }
    std::size_t size() const { return count_; }
    std::string version() const;
    /* "mdi:lightbulb" or "lightbulb" -> its codepoint; 0 for an unknown name, another prefix ("phu:..."), or no table. */
    std::uint32_t lookup(const std::string &name) const;

private:
    const unsigned char *data_ = nullptr;
    std::size_t len_ = 0;
    std::size_t count_ = 0;
    bool mapped_ = false;
};

/* The process' table: set_mdi_path() opens it (HA_MDI_NAMES in the environment wins over the path), once, at start
 * before the connection thread runs; until then mdi() is an empty table (every lookup 0). */
void set_mdi_path(const std::string &path);
const MdiNames &mdi();

/* A codepoint as UTF-8 ("" for 0 or an invalid one). */
std::string utf8_of(std::uint32_t cp);

} // namespace ha
